package PVE::API2::Qemu::Agent;

use strict;
use warnings;

use JSON;
use MIME::Base64 qw(encode_base64 decode_base64);

use PVE::JSONSchema qw(get_standard_option);
use PVE::RESTHandler;

use PVE::QemuConfig;
use PVE::QemuServer;
use PVE::QemuServer::Agent qw(agent_cmd check_agent_error);
use PVE::QemuServer::Monitor qw(mon_cmd);

use base qw(PVE::RESTHandler);

# max size for file-read over the api
my $MAX_READ_SIZE = 16 * 1024 * 1024; # 16 MiB

# list of commands
# will generate one api endpoint per command
# needs a 'method' property and a 'perms' property
my $guest_agent_commands = {
    'ping' => {
        method => 'POST',
        perms => 'VM.GuestAgent.Audit',
    },
    'get-time' => {
        return $res;
    },
});

__PACKAGE__->register_method({
    name => 'file-read',
    path => 'file-read',
    method => 'GET',
    protected => 1,
    proxyto => 'node',
    description => "Reads the given file via guest agent. Is limited to $MAX_READ_SIZE bytes.",
    permissions => {
        check => [
            'perm',
            '/vms/{vmid}',
            ['VM.GuestAgent.FileRead', 'VM.GuestAgent.Unrestricted'],
            any => 1,
        ],
    },
    parameters => {
        additionalProperties => 0,
        properties => {
            node => get_standard_option('pve-node'),
            vmid => get_standard_option(
                'pve-vmid',
                { completion => \&PVE::QemuServer::complete_vmid_running },
            ),
            count => {
                type => 'integer',
                optional => 1,
                minimum => 1,
                maximum => $MAX_READ_SIZE,
                default => $MAX_READ_SIZE,
                description => "Number of bytes to read.",
            },
            decode => {
                type => 'boolean',
                optional => 1,
                default => 1,
                description => "Data received from the QEMU Guest-Agent is base64 encoded."
                    . " If this is set to true, the data is decoded."
                    . " Otherwise the content is forwarded with base64 encoding."
                    . " Defaults to true.",
            },
            file => {
                type => 'string',
                description => 'The path to the file',
            },
            offset => {
                type => 'integer',
                optional => 1,
                minimum => 0,
                default => 0,
                description => "Offset to start reading at",
            },
        },
    },
    returns => {
        type => 'object',
        description => "Returns an object with a `content` property.",
        properties => {
            content => {
                type => 'string',
                description => "The content of the file, maximum $MAX_READ_SIZE",
            },
            truncated => {
                type => 'boolean',
                optional => 1,
                description => "If set to 1, the read did not reach the end of the file.",
            },
        },
    },
    code => sub {
        my ($param) = @_;
        my $count = $param->{count} // $MAX_READ_SIZE;
        my $decode = $param->{decode} // 1;
        my $offset = $param->{offset} // 0;

        my $vmid = $param->{vmid};
        my $conf = PVE::QemuConfig->load_config($vmid);

        my $qgafh =
            agent_cmd($vmid, $conf, "file-open", { path => $param->{file} }, "can't open file");

        if ($offset > 0) {
            my $seek = mon_cmd(
                $vmid, "guest-file-seek",
                handle => $qgafh,
                offset => int($offset),
                whence => 'set',
            );
            check_agent_error($seek, "can't seek to offset position");
        }

        my $bytes_read = 0;
        my $eof = 0;
        my $read_size = 1024 * 1024;
        my $content = "";

        while ($bytes_read < $count && !$eof) {
            my $bytes_left = $count - $bytes_read;
            my $chunk_size = $bytes_left < $read_size ? $bytes_left : $read_size;
            my $read =
                mon_cmd($vmid, "guest-file-read", handle => $qgafh, count => int($chunk_size));
            check_agent_error($read, "can't read from file");

            my $chunk = $read->{'buf-b64'};
            $chunk = decode_base64($chunk) if $decode;
            $content .= $chunk;

            $bytes_read += $read->{count};
            $eof = $read->{eof} // 0;
        }

        my $res = mon_cmd($vmid, "guest-file-close", handle => $qgafh);
        check_agent_error($res, "can't close file", 1);

        my $result = {
            content => $content,
            'bytes-read' => $bytes_read,
        };

        if (!$eof) {
            if (!defined($param->{count})) {
                warn "agent file-read: reached maximum read size: $MAX_READ_SIZE bytes."
                    . " output might be truncated.\n";
            }
            $result->{truncated} = 1;
        }

        return $result;
    },
});

__PACKAGE__->register_method({
    name => 'file-write',
    path => 'file-write',
    method => 'POST',
    protected => 1,
    proxyto => 'node',
    description => "Writes the given file via guest agent.",

